from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
from collections import defaultdict

# Load the workbook
wb = load_workbook("input.xlsx")
ws = wb["sheet1"]

# Define ranges
source_range = ws["A:C"]
helper_column = ws["J"]
output_range = ws["F2:H10"]

# Helper functions
def is_header(row):
    return row[0].value == "ITEM" and row[1].value == "NAME" and row[2].value == "REF"

def is_empty(row):
    return all(cell.value is None for cell in row)

def get_key(row):
    return (row[1].value, row[2].value)

# Collect data from source range
data = []
for row in source_range:
    if is_header(row):
        continue
    if is_empty(row):
        continue
    data.append(row)

# Collect unique names from helper column J
helper_names = set()
for cell in helper_column:
    if cell.value and not is_header(cell):
        helper_names.add(cell.value)

# Group data by (NAME, REF)
grouped_data = defaultdict(list)
for row in data:
    key = get_key(row)
    grouped_data[key].append(row)

# Prepare sorted data
sorted_data = []

# First, process rows with names in helper column J
for name in helper_names:
    for key, rows in grouped_data.items():
        if key[0] == name:
            for row in rows:
                sorted_data.append(row)

# Then, process remaining rows not in helper column J
for key, rows in grouped_data.items():
    if key[0] not in helper_names:
        for row in rows:
            sorted_data.append(row)

# Sort the second column (H) lowest to highest
sorted_data.sort(key=lambda x: x[2].value)

# Write the result to output range
for i, row in enumerate(sorted_data):
    if i >= len(output_range):
        break
    ws[f"G{i + 2}"] = row[1].value  # NAME from column B
    ws[f"H{i + 2}"] = row[2].value  # REF from column C

# Save the workbook
wb.save("output.xlsx")
